from jinja2 import Markup
from flask import request, session, current_app
import flask_tasks
from wtforms.fields import HiddenField
from wtforms.ext.csrf.session import SessionSecureForm

class DefaultPlaceholder():
    '''Placeholder for unspecified variables that should be set to defaults.'''
    pass

class SecureForm(SessionSecureForm):
    """
    Flask-specific subclass of WTForms **SessionSecureForm**.

    Auto‑loads request data when formdata is omitted,
    resolves CSRF settings from app config or form attributes,
    uses session as default csrf_context, and offers helpers
    like hidden_tag() and validate_on_submit().
    """

    def __init__(self, formdata=DefaultPlaceholder, obj=None, prefix='', csrf_context=None,
                 secret_key=None, csrf_enabled=None, *args, **kwargs):
        # CSRF flag resolution
        self.csrf_enabled = csrf_enabled if csrf_enabled is not None else current_app.config.get('CSRF_ENABLED', True)

        # Auto‑populate formdata on submission
        if formdata is DefaultPlaceholder:
            if self.is_submitted():
                formdata = request.form
                if request.files:
                    formdata = formdata.copy()
                    formdata.update(request.files)
                elif request.json:
                    formdata = werkzeug.datastructures.MultiDict(request.json)
            else:
                formdata = None

        # CSRF context and key handling
        if self.csrf_enabled:
            csrf_context = csrf_context or session
            secret_key = secret_key or getattr(self, "SECRET_KEY", None) or \
                         current_app.config.get("SECRET_KEY") or \
                         (session.secret_key if session else None)
            if secret_key is None:
                raise Exception('Must provide secret_key to use csrf.')
            self.SECRET_KEY = secret_key
        else:
            csrf_context = {}
            self.SECRET_KEY = ""

        super(SecureForm, self).__init__(formdata, obj, prefix, csrf_context=csrf_context, *args, **kwargs)

    def generate_csrf_token(self, csrf_context=None):
        return None if not self.csrf_enabled else super(SecureForm, self).generate_csrf_token(csrf_context)

    def validate_csrf_token(self, field):
        if self.csrf_enabled:
            super(SecureForm, self).validate_csrf_token(field)

    def is_submitted(self):
        return request and request.method in ("PUT", "POST")

    def hidden_tag(self, *fields):
        if not fields:
            fields = [f for f in self if isinstance(f, HiddenField)]
        parts = [u'<div style="display:none;">'] + \
                [unicode(getattr(self, f) if isinstance(f, basestring) else f) for f in fields] + \
                [u"</div>"]
        return Markup(u"".join(parts))

    def validate_on_submit(self):
        return self.is_submitted() and self.validate()

