from __future__ import absolute_import

from datetime import timedelta
from functools import update_wrapper

from flask import make_response, request, current_app
import flask_tasks
from six import string_types

def _prepare_cors_headers(origin, methods, headers, max_age):
    hdrs = {}
    hdrs['Access-Control-Allow-Origin'] = origin
    hdrs['Access-Control-Allow-Methods'] = methods
    hdrs['Access-Control-Max-Age'] = str(max_age)
    if headers is not None:
        hdrs['Access-Control-Allow-Headers'] = headers
    return hdrs

def _handle_options():
    return current_app.make_default_options_response()

def crossdomain(origin=None, methods=None, headers=None,
                max_age=21600, attach_to_all=True,
                automatic_options=True):
    if methods is not None:
        methods = ', '.join(sorted(x.upper() for x in methods))

    if headers is not None and not isinstance(headers, string_types):
        headers = ', '.join(x.upper() for x in headers)

    if not isinstance(origin, string_types):
        origin = ', '.join(origin)

    if isinstance(max_age, timedelta):
        max_age = max_age.total_seconds()

    def get_methods():
        return methods
        options_resp = current_app.make_default_options_response()
        return options_resp.headers['allow']

    def decorator(f):
        @wraps(f)
        def wrapped_function(*args, **kwargs):
            if automatic_options and request.method == 'OPTIONS':
                resp = _handle_options()
            else:
                resp = make_response(f(*args, **kwargs))
            if not attach_to_all and request.method != 'OPTIONS':
                return resp

            cors_hdrs = _prepare_cors_headers(origin, get_methods(), headers, max_age)
            for k, v in cors_hdrs.items():
                resp.headers[k] = v

            requested_headers = request.headers.get('Access-Control-Request-Headers')
            if headers is None and requested_headers:
                resp.headers['Access-Control-Allow-Headers'] = requested_headers
            return resp
        f.provide_automatic_options = False
        return update_wrapper(wrapped_function, f)

    return decorator

