from collections import OrderedDict
import random

from flask import current_app
import flask_tasks

from ..extensions import cache
from ..campaign.constants import (
    SEGMENT_BY_LOCATION,
    INCLUDE_SPECIAL_BEFORE,
    INCLUDE_SPECIAL_AFTER,
    INCLUDE_SPECIAL_ONLY,
    INCLUDE_SPECIAL_FIRST,
    INCLUDE_SPECIAL_FALLBACK,
)

class CampaignToolkit:
    """
    Toolkit providing helper methods for campaign location validation
    and target resolution.
    """

    @staticmethod
    def check_location(location, campaign, cache=cache):
        campaign_data = campaign.get_campaign_data(cache)
        return campaign_data.data_provider.get_location(
            campaign.locate_by, location
        )

    @staticmethod
    def find_targets(location, campaign, skip_special=False, cache=cache):
        """
        Retrieve target IDs for a given location, respecting campaign
        segmentation, special target rules, and ordering preferences.
        """
        if campaign.segment_by and campaign.segment_by != SEGMENT_BY_LOCATION:
            current_app.logger.error(
                'Called find_targets on campaign where segment_by=%s (%s)'
                % (campaign.segment_by, campaign.id)
            )
            return []

        campaign_data = campaign.get_campaign_data(cache)
        location_targets = campaign_data.get_targets_for_campaign(location, campaign)
        special_targets = [t.key for t in campaign.target_set]

        if skip_special:
            return location_targets

        if campaign.target_set:
            if campaign.target_ordering == 'shuffle':
                random.shuffle(special_targets)

            if campaign.include_special == INCLUDE_SPECIAL_BEFORE:
                combined = special_targets + location_targets
                return list(OrderedDict.fromkeys(combined))
            elif campaign.include_special == INCLUDE_SPECIAL_AFTER:
                combined = location_targets + special_targets
                return list(OrderedDict.fromkeys(combined))
            elif campaign.include_special == INCLUDE_SPECIAL_ONLY:
                overlap_list = [
                    t
                    for l in location_targets
                    for t in special_targets
                    if t.startswith(l) and t not in overlap_list
                ]
                if campaign.target_ordering == 'shuffle':
                    random.shuffle(overlap_list)
                return overlap_list
            elif campaign.include_special == INCLUDE_SPECIAL_FIRST:
                first_targets = [
                    t
                    for l in location_targets
                    for t in special_targets
                    if t.startswith(l) and t not in first_targets
                ]
                if campaign.target_ordering == 'shuffle':
                    random.shuffle(special_targets)
                combined = first_targets + special_targets
                return list(OrderedDict.fromkeys(combined))
            elif campaign.include_special == INCLUDE_SPECIAL_FALLBACK:
                first_targets = [
                    t
                    for l in location_targets
                    for t in special_targets
                    if t.startswith(l) and t not in first_targets
                ]
                return first_targets if first_targets else location_targets
            else:
                return special_targets
        else:
            return location_targets

