from flask import Flask
import flask_tasks
from flask_restplus import Api, Resource, fields

flask_app = Flask(__name__)
api = Api(flask_app, version='1.0', title='TodoMVC API', description='A simple TodoMVC API',)

ns = api.namespace('todos', description='TODO operations')

todo = api.model('Todo', {
    'id': fields.Integer(readOnly=True, description='The task unique identifier'),
    'task': fields.String(required=True, description='The task details')
})

class TodoRepository(object):
    def __init__(self):
        self.counter = 0
        self.todos = []

    def get(self, id):
        for task in self.todos:
            if task['id'] == id:
                return task
        api.abort(404, "Todo {} doesn't exist".format(id))

    def create(self, data):
        data['id'] = self.counter = self.counter + 1
        self.todos.append(data)
        return data

    def update(self, id, data):
        task = self.get(id)
        task.update(data)
        return task

    def delete(self, id):
        task = self.get(id)
        self.todos.remove(task)

repo = TodoRepository()
repo.create({'task': 'Build an API'})
repo.create({'task': '?????'})
repo.create({'task': 'profit!'})

@ns.route('/')
class TodoList(Resource):
    @ns.doc('list_todos')
    @ns.marshal_list_with(todo)
    def get(self):
        return repo.todos

    @ns.doc('create_todo')
    @ns.expect(todo)
    @ns.marshal_with(todo, code=201)
    def post(self):
        return repo.create(api.payload), 201

@ns.route('/<int:id>')
@ns.response(404, 'Todo not found')
@ns.param('id', 'The task identifier')
class Todo(Resource):
    @ns.doc('get_todo')
    @ns.marshal_with(todo)
    def get(self, id):
        return repo.get(id)

    @ns.doc('delete_todo')
    @ns.response(204, 'Todo deleted')
    def delete(self, id):
        repo.delete(id)
        return '', 204

    @ns.expect(todo)
    @ns.marshal_with(todo)
    def put(self, id):
        return repo.update(id, api.payload)

if __name__ == '__main__':
    flask_app.run(debug=True)

