from webapp.extensions import oid, facebook, twitter
from webapp.models import db, User
from webapp.forms import LoginForm, RegisterForm, OpenIDForm

main_bp = Blueprint(
    'main',
    __name__,
    template_folder='../templates/main',
)

@main_bp.route('/')
def index():
    return redirect(url_for('blog.home'))

@main_bp.route('/login', methods=['GET', 'POST'])
@oid.loginhandler
def login():
    form = LoginForm()
    openid_form = OpenIDForm()

    if openid_form.validate_on_submit():
        return oid.try_login(
            openid_form.openid.data,
            ask_for=['nickname', 'email'],
            ask_for_optional=['fullname'],
        )

    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).one()
        login_user(user, remember=form.remember.data)

        identity_changed.send(
            current_app._get_current_object(), identity=Identity(user.id)
        )

        flash('You have been logged in.', category='success')
        return redirect(url_for('blog.home'))

    openid_errors = oid.fetch_error()
    if openid_errors:
        flash(openid_errors, category='danger')

    return render_template('login.html', form=form, openid_form=openid_form)

@main_bp.route('/facebook')
def facebook_login():
    return facebook.authorize(
        callback=url_for(
            '.facebook_authorized',
            next=request.referrer or None,
            _external=True,
        )
    )

@main_bp.route('/facebook/authorized')
@facebook.authorized_handler
def facebook_authorized(resp):
    if resp is None:
        return 'Access denied: reason=%s error=%s' % (
            request.args['error_reason'],
            request.args['error_description'],
        )

    session['facebook_oauth_token'] = (resp['access_token'], '')

    me = facebook.get('/me')
    user = User.query.filter_by(
        username=me.data['first_name'] + ' ' + me.data['last_name']
    ).first()

    if not user:
        user = User(me.data['first_name'] + ' ' + me.data['last_name'])
        db.session.add(user)
        db.session.commit()

    login_user(user)
    flash('You have been logged in.', category='success')
    return redirect(request.args.get('next') or url_for('blog.home'))

@main_bp.route('/twitter-login')
def twitter_login():
    return twitter.authorize(
        callback=url_for(
            '.twitter_authorized',
            next=request.referrer or None,
            _external=True,
        )
    )

@main_bp.route('/twitter-login/authorized')
@twitter.authorized_handler
def twitter_authorized(resp):
    if resp is None:
        return 'Access denied: reason=%s error=%s' % (
            request.args['error_reason'],
            request.args['error_description'],
        )

    session['twitter_oauth_token'] = resp['oauth_token'] + resp['oauth_token_secret']

    user = User.query.filter_by(username=resp['screen_name']).first()
    if not user:
        user = User(resp['screen_name'], '')
        db.session.add(user)
        db.session.commit()

    login_user(user)
    flash('You have been logged in.', category='success')
    return redirect(request.args.get('next') or url_for('blog.home'))

@main_bp.route('/logout', methods=['GET', 'POST'])
def logout():
    logout_user()

    identity_changed.send(
        current_app._get_current_object(), identity=AnonymousIdentity()
    )

    flash('You have been logged out.', category='success')
    return redirect(url_for('.login'))

@main_bp.route('/register', methods=['GET', 'POST'])
@oid.loginhandler
def register():
    form = RegisterForm()
    openid_form = OpenIDForm()

    if openid_form.validate_on_submit():
        return oid.try_login(
            openid_form.openid.data,
            ask_for=['nickname', 'email'],
            ask_for_optional=['fullname'],
        )

    if form.validate_on_submit():
        new_user = User(form.username.data)
        new_user.set_password(form.password.data)

        db.session.add(new_user)
        db.session.commit()

        flash('Your user has been created, please login.', category='success')
        return redirect(url_for('.login'))

    openid_errors = oid.fetch_error()
    if openid_errors:
        flash(openid_errors, category='danger')

    return render_template('register.html', form=form, openid_form=openid_form)


def create_app():
    app = __import__('flask').Flask(__name__)
    app.secret_key = 'super-secret-key'

    app.register_blueprint(main_bp)
    return app


