"""
Treadmill IPA REST api.
"""

import flask
import flask_tasks
import flask_restplus as restplus
from flask_restplus import fields

# Disable E0611: No 'name' in module
from treadmill import webutils  # pylint: disable=E0611


def api_error_handler(func):
    """Wraps a Flask view and returns 400 on any exception."""
    def wrapper(*args):
        try:
            return func(*args)
        except Exception as e:  # pylint: disable=broad-except
            return flask.abort(400, {'message': getattr(e, 'message', str(e))})
    return wrapper


def register_routes(api, cors, impl):
    """Configures REST handlers for ipa resource."""
    namespace = webutils.namespace(
        api, __name__, 'IPA REST operations'
    )

    service_request_model = {
        'hostname': fields.String(description='Hostname'),
        'domain': fields.String(description='Domain')
    }

    service_model = api.model(
        'service', service_request_model
    )

    @namespace.route('/host/<hostname>')
    @api.doc(params={'hostname': 'Hostname'})
    class HostResource(restplus.Resource):
        """Treadmill IPA Host"""

        @webutils.post_api(
            api,
            cors,
        )
        def post(self, hostname):
            """Adds host to IPA."""
            return impl.add_host(hostname)

        @webutils.delete_api(
            api,
            cors,
        )
        def delete(self, hostname):
            """Deletes host from IPA."""
            return impl.delete_host(hostname)

    @namespace.route('/user/<username>')
    @api.doc(params={'username': 'Username'})
    class UserResource(restplus.Resource):
        """Treadmill IPA User"""

        @webutils.post_api(
            api,
            cors,
        )
        @api_error_handler
        def post(self, username):
            """Adds User to IPA."""
            impl.add_user(username)

        @webutils.delete_api(
            api,
            cors,
        )
        @api_error_handler
        def delete(self, username):
            """Deletes User from IPA."""
            return impl.delete_user(username)

    @namespace.route('/service/<service>')
    @api.doc(params={'service': 'Service'})
    class ServiceResource(restplus.Resource):
        """Treadmill IPA Service"""

        @webutils.post_api(
            api,
            cors,
            req_model=service_model
        )
        def post(self, service):
            """Add Service to IPA"""
            return impl.service_add(service, flask.request.json)

