from flask import Blueprint, jsonify as flask_jsonify, request
import flask_tasks
from flask import redirect, make_response, url_for
import flask_tasks

from grano.lib.serialisation import jsonify as grano_jsonify
from grano.lib.args import object_or_404, request_data
from grano.model import Permission, Project
from grano.views.cache import validate_cache
from grano.logic import permissions
from grano.lib.pager import Pager
from grano.lib.exc import Gone
from grano.core import app, db
from grano import authz

permissions_api = Blueprint('permissions_api', __name__)


def _get_project(slug):
    return object_or_404(Project.by_slug(slug))


def _get_permission(project, id):
    return object_or_404(Permission.by_project_and_id(project, id))


@permissions_api.route('/api/1/projects/<slug>/permissions', methods=['GET'])
def index(slug):
    project = _get_project(slug)
    authz.require(authz.project_manage(project))
    query = Permission.all().filter_by(project=project)
    pager = Pager(query, slug=slug)
    validate_cache(keys=pager.cache_keys())
    return grano_jsonify(pager, index=True)


@permissions_api.route('/api/1/projects/<slug>/permissions', methods=['POST', 'PUT'])
def create(slug):
    project = _get_project(slug)
    authz.require(authz.project_manage(project))
    data = request_data({'project': project})
    permission = permissions.save(data)
    db.session.commit()
    return grano_jsonify(permission, status=201)


@permissions_api.route('/api/1/projects/<slug>/permissions/<id>', methods=['GET'])
def view(slug, id):
    project = _get_project(slug)
    permission = _get_permission(project, id)
    authz.require(authz.project_manage(project) or request.account == permission.account)
    return grano_jsonify(permission)


@permissions_api.route('/api/1/projects/<slug>/permissions/<id>', methods=['POST', 'PUT'])
def update(slug, id):
    project = _get_project(slug)
    authz.require(authz.project_manage(project))
    permission = _get_permission(project, id)
    data = request_data({'project': project})
    permission = permissions.save(data, permission=permission)
    db.session.commit()
    return grano_jsonify(permission)


@permissions_api.route('/api/1/projects/<slug>/permissions/<id>', methods=['DELETE'])
def delete(slug, id):
    project = _get_project(slug)
    authz.require(authz.project_manage(project))
    permission = _get_permission(project, id)
    permissions.delete(permission)
    db.session.commit()
    raise Gone()
